Translate("frFR", "kingdom-of-stormwind", {
	title = "Royaume de Stormwind",
	sections = {
		{
			title = "Résumé",
			text = [=[Le royaume de Stormwind est le plus grand royaume humain encore debout dans les {link:eastern-kingdoms}Royaumes de l'est{/link}. Son cœur est la cité blanche de {link:stormwind-city}Stormwind{/link}, et autour d'elle s'étendent les forêts d'{link:elwynn-forest}Elwynn{/link}, les champs de la {link:westfall}Marche de l'Ouest{/link}, les collines des {link:redridge-mountains}Carmines{/link} et les bois ombreux du {link:duskwood}Bois de la Pénombre{/link}. Deux fois brisé et deux fois rebâti, il dirige aujourd'hui l'{link:alliance}Alliance{/link}. Pourtant son trône est vide, son armée est loin de chez elle, et ses frontières sont pleines d'ennemis.]=],
		},
		{
			title = "Origines",
			text = [=[Quand l'empire d'{link:arathor}Arathor{/link} commença à se désagréger, les derniers héritiers de la lignée {link:arathi-highlands}Arathi{/link} quittèrent l'ancienne capitale de {link:stromgarde-keep}Strom{/link} et partirent vers le sud. Dans une terre verte et abritée, ils fondèrent un nouveau royaume et le nommèrent {link:azeroth}Azeroth{/link}. Sa capitale était {link:stormwind-city}Stormwind{/link}. Le royaume devint riche et autosuffisant, et pendant de nombreux siècles il se tint à l'écart des querelles des royaumes du nord. La foi de la {link:holy-light}Lumière sacrée{/link} y prit profondément racine, et les clercs de {link:northshire-abbey}Northshire{/link} gardaient ses plus anciens livres.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La Première Guerre.{/b} La {link:horde}Horde{/link} orque franchit la {link:dark-portal}Porte des Ténèbres{/link} et entra dans les marais du sud, et le royaume d'{link:azeroth}Azeroth{/link} porta tout le poids de la {link:first-war}Première Guerre{/link}. Ses fermes et ses villages brûlèrent. {link:stormwind-city}Stormwind{/link} elle-même finit par tomber, et le roi {link:llane-wrynn}Llane Wrynn{/link} fut tué dans son propre donjon. Sire {link:anduin-lothar}Anduin Lothar{/link} mena les survivants par-delà la mer jusqu'à {link:lordaeron}Lordaeron{/link}, avec parmi eux {link:varian-wrynn}Varian{/link}, le jeune fils du roi.
• {b}La Deuxième Guerre.{/b} L'avertissement de Lothar poussa le roi {link:terenas-menethil}Terenas Menethil{/link} à lever l'{link:alliance}Alliance de Lordaeron{/link}. Les exilés de Stormwind combattirent pendant la {link:second-war}Deuxième Guerre{/link} aux côtés des royaumes du nord jusqu'à ce que la Horde soit brisée.
• {b}La reconstruction.{/b} Les exilés rentrèrent chez eux pour trouver des ruines. Varian fut couronné roi, et la {link:stonemasons-guild}Guilde des tailleurs de pierre{/link} releva la cité de ses décombres. Quand la {link:house-of-nobles}Chambre des nobles{/link} refusa de payer les maçons, des émeutes emplirent les rues, et la reine {link:tiffin-wrynn}Tiffin Wrynn{/link} mourut dans le chaos. Les maçons furent chassés, et d'eux naquit la {link:defias-brotherhood}Confrérie défias{/link}.
• {b}La Troisième Guerre.{/b} Tandis que la peste détruisait Lordaeron, Stormwind fut épargnée par le pire de la {link:third-war}Troisième Guerre{/link}. Quand le royaume du nord tomba, Stormwind devint la première puissance de l'Alliance.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:stormwind-city}Stormwind{/link} est un royaume sans son roi. {link:varian-wrynn}Varian Wrynn{/link} a disparu, et nul ne peut dire où il est allé. Le généralissime {link:bolvar-fordragon}Bolvar Fordragon{/link} gouverne en tant que régent au nom du jeune prince, {link:anduin-wrynn}Anduin Wrynn{/link}. À la cour, dame {link:katrana-prestor}Katrana Prestor{/link} a gagné l'oreille des nobles et une grande part de la confiance du régent. L'armée est partie loin, et le cœur du royaume doit être tenu par de maigres garnisons et des volontaires. La {link:westfall}Marche de l'Ouest{/link} est tombée aux mains des {link:defias-brotherhood}Défias{/link}. Des {link:riverpaw-gnolls}gnolls{/link} et des {link:kobolds}kobolds{/link} s'en prennent à {link:elwynn-forest}Elwynn{/link}, des orcs du {link:blackrock-clan}clan Blackrock{/link} pressent les {link:redridge-mountains}Carmines{/link}, et les morts marchent dans le {link:duskwood}Bois de la Pénombre{/link}. Des agents du {link:si-7}SI:7{/link} œuvrent dans l'ombre, mais les maux du royaume sont nombreux et ses défenseurs peu nombreux.]=],
		},
	},
})

Translate("frFR", "arathor", {
	title = "Arathor",
	sections = {
		{
			title = "Résumé",
			text = [=[Arathor fut la première nation des {link:humans}humains{/link}. Elle fut forgée dans la guerre contre les trolls, et elle fut sauvée par une alliance avec les elfes. D'elle vinrent tous les royaumes humains du nord et du sud. Arathor elle-même a disparu depuis plus de mille ans, mais son sang et ses bannières sont encore rappelés partout où règnent les humains.]=],
		},
		{
			title = "Origines",
			text = [=[Près de trois mille ans avant la {link:dark-portal}Porte des Ténèbres{/link}, les tribus humaines du nord étaient dispersées et en guerre les unes contre les autres. Les {link:trolls}trolls{/link} Amani les razziaient sans pitié. Alors {link:thoradin}Thoradin{/link}, seigneur de guerre de la tribu {link:arathi-highlands}Arathi{/link}, résolut que l'humanité devait s'unir ou périr. Par le mariage, par la promesse et par l'épée, il réunit les tribus sous une seule bannière. Il nomma son royaume Arathor, et il éleva sa capitale, la cité-forteresse de {link:stromgarde-keep}Strom{/link}, dans les hautes terres qui portent encore le nom d'Arathi.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les guerres des {link:trolls}Trolls{/link}.{/b} Quand les Amani fondirent sur {link:quel-thalas}Quel'Thalas{/link}, les elfes envoyèrent des émissaires à {link:stromgarde-keep}Strom{/link}. En échange des épées d'Arathor, ils acceptèrent d'enseigner les voies de la {link:arcane-magic}magie{/link} à cent humains. Ensemble, elfes et hommes brisèrent les Amani au pied des montagnes d'{link:alterac-mountains}Alterac{/link}. Les {link:troll-wars}guerres des Trolls{/link} prirent fin, et les elfes jurèrent une amitié durable à la lignée de {link:thoradin}Thoradin{/link}.
• {b}L'expansion.{/b} Après Thoradin, le peuple d'Arathor se répandit bien au-delà de Strom. Il fonda {link:dalaran}Dalaran{/link}, les ports de {link:gilneas}Gilneas{/link}, le royaume insulaire de {link:kul-tiras}Kul Tiras{/link}, le siège montagnard d'Alterac et les riches terres de {link:lordaeron}Lordaeron{/link}. Chaque cité devint plus forte, et chacune devint davantage sa propre maîtresse.
• {b}Le morcellement.{/b} Strom, pauvre en terres et en commerce, perdit lentement son emprise. Ses grandes familles partirent vers le nord, à Lordaeron. Les derniers héritiers de la lignée {link:arathi-highlands}Arathi{/link} firent voile vers le sud et fondèrent le royaume qui devint le {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Strom fut laissée à quelques maisons régnantes, qui la rebaptisèrent Stromgarde. L'empire était devenu sept royaumes.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Arathor ne survit plus qu'à travers ses héritiers. Les sept royaumes furent réunis une fois encore, dans l'{link:alliance}Alliance de Lordaeron{/link}, sous {link:anduin-lothar}Anduin Lothar{/link}, le dernier du sang de {link:thoradin}Thoradin{/link}. Aujourd'hui, les hautes terres de {link:stromgarde-keep}Strom{/link} sont un pays de ruines, disputé par les orcs, les trolls, les ogres et les brigands du {link:syndicate}Syndicat{/link}.]=],
		},
	},
})

Translate("frFR", "lordaeron", {
	title = "Lordaeron",
	sections = {
		{
			title = "Résumé",
			text = [=[Lordaeron était le plus puissant des royaumes humains. Depuis sa Capitale, dans les clairières de {link:tirisfal-glades}Tirisfal{/link}, ses rois gouvernaient les terres du nord et menèrent l'{link:alliance}Alliance{/link} qui sauva l'humanité pendant la {link:second-war}Deuxième Guerre{/link}. Il tomba pendant la {link:third-war}Troisième Guerre{/link}, trahi de l'intérieur par son propre prince. Ses terres sont aujourd'hui le royaume des morts.]=],
		},
		{
			title = "Origines",
			text = [=[Au temps d'{link:arathor}Arathor{/link}, des colons prirent les clairières fertiles de {link:tirisfal-glades}Tirisfal{/link} et nommèrent la terre d'après Lordain, un général des guerres des {link:trolls}Trolls{/link}. Quand {link:stromgarde-keep}Strom{/link} déclina, beaucoup de ses familles nobles transportèrent leurs domaines au nord, dans ces riches campagnes. Elles firent de Lordaeron un royaume à part entière, et ses frontières s'étendirent rapidement. Lordaeron était aussi une terre de foi. Des pèlerins venaient de loin à ses monastères, en quête de guérison et de sagesse dans la {link:holy-light}Lumière sacrée{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Quand sire {link:anduin-lothar}Anduin Lothar{/link} amena les survivants de {link:stormwind-city}Stormwind{/link} au nord, le roi {link:terenas-menethil}Terenas Menethil{/link} les accueillit. Il convoqua ensuite les souverains des royaumes humains et leva l'{link:alliance}Alliance de Lordaeron{/link}. Sous le commandement de Lothar, elle repoussa la {link:horde}Horde{/link} à travers la {link:dark-portal}Porte des Ténèbres{/link}.
• {b}La paix fragile.{/b} Les orcs vaincus furent gardés dans des camps d'internement à travers Lordaeron, à grands frais. Ce fardeau divisa l'Alliance. {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} et {link:quel-thalas}Quel'Thalas{/link} la quittèrent, et le royaume de Terenas en fut affaibli.
• {b}La peste.{/b} Pendant la {link:third-war}Troisième Guerre{/link}, le {link:cult-of-the-damned}culte des Damnés{/link} répandit une peste par le grain des terres du nord, et les morts se relevèrent par milliers. Le prince {link:arthas-menethil}Arthas Menethil{/link} incendia la cité pestiférée de Stratholme lors de l'{link:culling-of-stratholme}Épuration{/link}, puis poursuivit les maîtres de la peste jusqu'en Norfendre. Il revint en chevalier de la mort du {link:scourge}Fléau{/link} et tua son père sur son trône. Ce fut la {link:fall-of-lordaeron}chute de Lordaeron{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Lordaeron est un royaume de cadavres. Le {link:scourge}Fléau{/link} tient les {link:eastern-plaguelands}Maleterres{/link}. Sous les ruines de la Capitale, les {link:forsaken}Réprouvés{/link} de {link:sylvanas-windrunner}Sylvanas Windrunner{/link} ont fait d'{link:undercity}Undercity{/link} leur foyer. La {link:scarlet-crusade}Croisade écarlate{/link} brûle tout ce qu'elle soupçonne de porter la peste, et l'{link:argent-dawn}Aube d'argent{/link} se dresse contre le Fléau aux côtés de quiconque veut l'aider. Aucun roi des vivants ne règne plus ici.]=],
		},
	},
})

Translate("frFR", "gilneas", {
	title = "Gilneas",
	sections = {
		{
			title = "Résumé",
			text = [=[Gilneas est un fier royaume humain sur une péninsule escarpée au sud des {link:silverpine-forest}Pins argentés{/link}. Son peuple est endurant et indépendant, et son armée comptait jadis parmi les plus fortes des sept royaumes. Après la {link:second-war}Deuxième Guerre{/link}, son roi coupa son royaume du monde derrière un grand mur. Ce qui se passe derrière ce mur, aucun étranger ne peut le dire.]=],
		},
		{
			title = "Origines",
			text = [=[Gilneas fut l'une des cités-États fondées par le peuple d'{link:arathor}Arathor{/link} après les guerres des {link:trolls}Trolls{/link}. Ses colons bâtirent de solides ports le long de la côte, et ses marins les plus hardis partirent fonder {link:kul-tiras}Kul Tiras{/link}. Incapable de rivaliser avec la flotte de Kul Tiras, Gilneas se tourna vers le commerce et les armes. Ses soldats étaient réputés égaux à tous ceux d'Arathor.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Le {link:genn-greymane}roi Genn Greymane{/link} rejoignit l'Alliance de Lordaeron sans grand amour pour elle. Il croyait que Gilneas pouvait se défendre seule, et il garda ses armées près de chez lui.
• {b}{link:the-greymane-wall}Le mur de Greymane{/link}.{/b} Après la guerre, le coût des camps d'internement orcs l'irrita. Greymane retira Gilneas de l'{link:alliance}Alliance{/link}. Il éleva ensuite un vaste mur le long de la frontière nord de son royaume et en ferma les portes. Le mur coupait les terres de ses propres nobles, laissant au-dehors des villages tels que {link:pyrewood-village}Bois-du-Bûcher{/link} et {link:ambermill}Moulin-de-l'Ambre{/link}.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Quand la peste balaya {link:lordaeron}Lordaeron{/link}, les portes de Gilneas restèrent fermées. Aucune armée ne sortit du sud pour secourir le royaume mourant.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:the-greymane-wall}Le mur de Greymane{/link} est toujours debout, et ses portes sont toujours closes. Au-delà, dans la {link:silverpine-forest}forêt des Pins argentés{/link}, le {link:scourge}Fléau{/link} et les {link:forsaken}Réprouvés{/link} se disputent les anciennes terres du nord. Les villageois laissés hors du mur doivent se débrouiller seuls. Ce qu'est devenu le royaume à l'intérieur n'est pas connu.]=],
		},
	},
})

Translate("frFR", "kul-tiras", {
	title = "Kul Tiras",
	sections = {
		{
			title = "Résumé",
			text = [=[Kul Tiras est un royaume insulaire de la Grande mer, à l'ouest de Khaz Modan. C'est une nation de marins et de charpentiers de marine, et sa flotte fut jadis la plus grande du monde. De la maison Proudmoore vinrent ses amiraux, et de ses ports partirent les flottes qui portèrent l'{link:alliance}Alliance{/link} à la guerre.]=],
		},
		{
			title = "Origines",
			text = [=[Des marins de {link:gilneas}Gilneas{/link} découvrirent au sud une grande île, riche en minerai et en bois. Certains y restèrent et y fondèrent un avant-poste maritime, qui devint un royaume à part entière. Kul Tiras prospéra grâce à la pêche et au commerce. Ses flottes marchandes voguaient sur toutes les côtes du monde connu, et au temps d'{link:arathor}Arathor{/link}, elle possédait la plus grande flotte de l'empire.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Le grand amiral {link:daelin-proudmoore}Daelin Proudmoore{/link} fit entrer les flottes de Kul Tiras dans l'{link:alliance}Alliance de Lordaeron{/link}. Ses navires combattirent les flottes orques sur les mers et ravitaillèrent les armées de l'Alliance. Le royaume paya un lourd tribut en navires et en hommes.
• {b}La paix fragile.{/b} Quand l'Alliance s'affaiblit après la guerre, Kul Tiras lui resta fidèle, mais elle se replia de plus en plus sur ses propres affaires.
• {b}{link:theramore-isle}Theramore{/link}.{/b} Après la {link:third-war}Troisième Guerre{/link}, la fille de Daelin, {link:jaina-proudmoore}Jaina Proudmoore{/link}, mena les survivants du nord en {link:kalimdor}Kalimdor{/link}, où elle fit la paix avec les orcs de {link:thrall}Thrall{/link}. Daelin refusa de l'accepter. Il vint avec sa flotte pour détruire la {link:horde}Horde{/link}, et il fut tué dans les combats devant les murs de Theramore.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Kul Tiras se trouve loin, de l'autre côté de la mer, et elle prend peu de part aux affaires du continent. Sur les côtes de {link:kalimdor}Kalimdor{/link}, des fusiliers marins de Kul Tiras tiennent encore le {link:northwatch-hold}Fort du Nord{/link} dans les {link:the-barrens}Tarides{/link} et le {link:tiragarde-keep}Donjon de Tiragarde{/link} en {link:durotar}Durotar{/link}. Ils n'ont pas pardonné à la {link:horde}Horde{/link} la mort de leur amiral.]=],
		},
	},
})

Translate("frFR", "dalaran", {
	title = "Dalaran",
	sections = {
		{
			title = "Résumé",
			text = [=[Dalaran est la cité des mages. Ce fut la première cité-État d'{link:arathor}Arathor{/link} à se gouverner elle-même, et pendant plus de deux mille ans elle fut le cœur de la magie humaine. Ses tours violettes s'élevaient au-dessus des rives du Lac Lordamere jusqu'à ce que le {link:scourge}Fléau{/link} et la {link:burning-legion}Légion ardente{/link} les abattent. Aujourd'hui, Dalaran s'est relevée dans les montagnes d'{link:alterac-mountains}Alterac{/link}, et ses mages en sont les seigneurs.]=],
		},
		{
			title = "Origines",
			text = [=[Dalaran commença comme un comptoir commercial au milieu d'{link:arathor}Arathor{/link}. Elle grandit rapidement, et elle devint un refuge pour les mages de l'empire, dont le peuple se méfiait. Sous le mage Ardogan, la cité gagna son indépendance vis-à-vis de {link:stromgarde-keep}Strom{/link} et fut gouvernée par des sorciers. Leur magie imprudente attira l'attention des démons. Pour les combattre en secret, les mages de Dalaran et les elfes de {link:quel-thalas}Quel'Thalas{/link} fondèrent {link:shadow-council}le Conseil{/link} de {link:tirisfal-glades}Tirisfal{/link}, dont les Gardiens défendirent le monde pendant des générations. Avec le temps, les mages de la cité formèrent le {link:kirin-tor}Kirin Tor{/link}, qui en vint à la gouverner.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Dalaran rejoignit l'{link:alliance}Alliance de Lordaeron{/link} et envoya ses mages combattre les orcs. Après la guerre, ses sorciers surveillèrent la {link:dark-portal}Porte des Ténèbres{/link} depuis {link:nethergarde-keep}Rempart-du-Néant{/link}.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Le nécromancien {link:kel-thuzad}Kel'Thuzad{/link}, autrefois mage de Dalaran, fonda le {link:cult-of-the-damned}culte des Damnés{/link}. À son instigation, {link:arthas-menethil}Arthas Menethil{/link} mena le {link:scourge}Fléau{/link} contre la cité et s'empara du livre de sorts de {link:medivh}Medivh{/link}. Grâce à lui, {link:archimonde}Archimonde{/link} fut invoqué dans le monde. Le seigneur démon écrasa Dalaran d'un seul sort et la laissa en ruine.
• {b}La reconstruction.{/b} Les mages survivants revinrent dans les ruines. Ils élevèrent une grande barrière violette au-dessus de la cité et la rebâtirent derrière ce bouclier, cachée du monde.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Dalaran se dresse, rebâtie, dans les montagnes d'{link:alterac-mountains}Alterac{/link}, et sa barrière a disparu. Nul hors du {link:kirin-tor}Kirin Tor{/link} ne peut encore dire pourquoi elle est tombée. La cité est de nouveau ouverte, et ses rues sont pleines de mages, de marchands et de banquiers. Mais tout ne va pas bien à l'intérieur. Des enchantements tournent mal, des créations arcaniques échappent à tout contrôle, et une énergie démoniaque s'agite dans les rues. Le Kirin Tor est fier, et il n'admet pas volontiers avoir besoin d'aide.]=],
		},
	},
})

Translate("frFR", "kirin-tor", {
	title = "Kirin Tor",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Kirin Tor rassemble les mages de {link:dalaran}Dalaran{/link} et les maîtres de cette cité. Ils sont les gardiens de la magie humaine : ses érudits, ses juges et ses gardiens. Ils revendiquent depuis longtemps le droit de surveiller chaque sort lancé dans les terres humaines, et ils gardent jalousement leurs secrets.]=],
		},
		{
			title = "Origines",
			text = [=[Quand l'empire d'{link:arathor}Arathor{/link} commença à se morceler, les mages de {link:dalaran}Dalaran{/link} formèrent une secte pour étudier et consigner chaque sort et chaque relique magique connus de l'humanité. Cette secte était le Kirin Tor. Elle devint l'ordre dirigeant de la cité, mené par un conseil de ses plus grands membres. Depuis leur Citadelle pourpre, ils jugeaient quelle magie pouvait être pratiquée, et laquelle devait être interdite.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les Gardiens.{/b} Pendant des siècles, le Kirin Tor travailla aux côtés du Conseil de {link:tirisfal-glades}Tirisfal{/link}, qui choisissait les Gardiens combattant les démons en secret. Le dernier Gardien fut {link:medivh}Medivh{/link}.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Les mages du Kirin Tor combattirent pour l'{link:alliance}Alliance de Lordaeron{/link}. Après la guerre, ils bâtirent {link:nethergarde-keep}Rempart-du-Néant{/link} près de la {link:dark-portal}Porte des Ténèbres{/link} pour surveiller la terre ravagée au-delà.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Le Kirin Tor avait chassé le mage {link:kel-thuzad}Kel'Thuzad{/link} pour son étude de la nécromancie. Il revint en maître du {link:cult-of-the-damned}culte des Damnés{/link}, et sa peste détruisit {link:lordaeron}Lordaeron{/link}. L'archimage Antonidas, chef de l'ordre, fut tué quand le {link:scourge}Fléau{/link} prit {link:dalaran}Dalaran{/link}.
• {b}Les worgens.{/b} Un mage de l'ordre, l'archimage {link:archmage-arugal}Arugal{/link}, invoqua les sauvages worgens pour combattre le Fléau dans la {link:silverpine-forest}forêt des Pins argentés{/link}. Ils se révélèrent une malédiction aussi grande que les morts-vivants. Arugal tient maintenant le {link:shadowfang-keep}Donjon d'Ombrecroc{/link}, et l'on dit qu'il a perdu l'esprit.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le Kirin Tor a rebâti {link:dalaran}Dalaran{/link} dans les montagnes d'{link:alterac-mountains}Alterac{/link}, et sa barrière est tombée. Dans la cité, ses sorts échouent et ses créations brisent leurs liens, et il peine à garder le contrôle de ses propres rues. Ses mages montent toujours la garde à {link:nethergarde-keep}Rempart-du-Néant{/link}, et certains d'entre eux se tiennent aux côtés de {link:jaina-proudmoore}Jaina Proudmoore{/link} à {link:theramore-isle}Theramore{/link}.]=],
		},
	},
})

Translate("frFR", "quel-thalas", {
	title = "Quel'Thalas",
	sections = {
		{
			title = "Résumé",
			text = [=[Quel'Thalas est le royaume des {link:high-elves}hauts-elfes{/link}, dans les forêts du nord de {link:lordaeron}Lordaeron{/link}. Pendant des milliers d'années, ce fut un royaume de printemps éternel, nourri par la magie du puits de Soleil. Pendant la {link:third-war}Troisième Guerre{/link}, le {link:scourge}Fléau{/link} franchit ses portes et souilla sa source sacrée. Ce qui reste du royaume est silencieux et lointain.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:great-sundering}Fracture{/link}, une troupe de Bien-nés exilés quitta {link:kalimdor}Kalimdor{/link}, bannie par les {link:night-elves}elfes de la nuit{/link} pour son amour de la magie. Menés par Dath'Remar Sunstrider, ils traversèrent la mer et s'installèrent au nord des {link:eastern-kingdoms}Royaumes de l'est{/link}. Là, ils fondèrent Quel'Thalas et élevèrent le puits de Soleil, une source de puissance arcanique. Des pierres runiques furent disposées dans les forêts pour cacher leur magie aux démons qu'elle pourrait attirer.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les guerres des {link:trolls}Trolls{/link}.{/b} Les trolls Amani faillirent submerger le jeune royaume. Les elfes demandèrent l'aide d'{link:arathor}Arathor{/link} et enseignèrent la magie à cent humains en échange de ses armées. Ensemble, ils brisèrent les Amani, et les elfes jurèrent amitié à la lignée de {link:thoradin}Thoradin{/link}.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Quand la {link:horde}Horde{/link} et les Amani mirent le feu aux forêts, le roi Anasterian Sunstrider honora sa vieille dette et rejoignit l'{link:alliance}Alliance de Lordaeron{/link}. Après la guerre, il jugea que l'Alliance avait failli envers son peuple, et il s'en retira.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Le prince {link:arthas-menethil}Arthas Menethil{/link} mena le {link:scourge}Fléau{/link} vers le nord. La générale des rôdeurs {link:sylvanas-windrunner}Sylvanas Windrunner{/link} le combattit à chaque porte et fut tuée. Arthas tua le roi Anasterian et se servit du puits de Soleil pour relever {link:kel-thuzad}Kel'Thuzad{/link} en liche. Le cœur du royaume elfique fut souillé.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Quel'Thalas se trouve au-delà des {link:eastern-plaguelands}Maleterres{/link}, coupé du sud par le {link:scourge}Fléau{/link}. Peu de messages en viennent. Les hauts-elfes qui restent dans les terres du sud vivent en petites bandes dispersées, comme les rôdeurs du {link:quel-danil-lodge}Gîte de Quel'Danil{/link} dans les {link:the-hinterlands}Hinterlands{/link}. Beaucoup d'entre eux pleurent un foyer qu'ils ne reverront peut-être jamais.]=],
		},
	},
})

Translate("frFR", "alliance", {
	title = "Alliance",
	aliases = { "Alliance de Lordaeron" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'Alliance est la ligue des peuples unis contre leurs ennemis communs. {link:humans}Humains{/link}, {link:dwarves}nains{/link}, {link:gnomes}gnomes{/link} et {link:night-elves}elfes de la nuit{/link} en font partie. Elle naquit pendant la {link:second-war}Deuxième Guerre{/link} pour affronter la {link:horde}Horde{/link} orque, et elle a été brisée et refaite depuis. Aujourd'hui, ses plus grandes puissances sont le {link:kingdom-of-stormwind}royaume de Stormwind{/link} et le {link:kingdom-of-ironforge}royaume d'Ironforge{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Quand {link:stormwind-city}Stormwind{/link} tomba pendant la {link:first-war}Première Guerre{/link}, sire {link:anduin-lothar}Anduin Lothar{/link} mena ses survivants à {link:lordaeron}Lordaeron{/link} et avertit que la {link:horde}Horde{/link} viendrait au nord. Le roi {link:terenas-menethil}Terenas Menethil{/link} l'écouta. Il convoqua les souverains des royaumes humains et les lia dans l'Alliance de Lordaeron, avec Lothar pour commandant suprême. Les nains d'{link:ironforge}Ironforge{/link}, les gnomes de {link:gnomeregan}Gnomeregan{/link} et les hauts-elfes de {link:quel-thalas}Quel'Thalas{/link} la rejoignirent aussi.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} L'Alliance affronta la {link:horde}Horde{/link} à travers le nord et la repoussa jusqu'au Pic {link:blackrock-mountain}Blackrock{/link}. {link:anduin-lothar}Lothar{/link} tomba lors des dernières batailles, et son lieutenant {link:turalyon}Turalyon{/link} mena la victoire finale. Les orcs survivants furent parqués dans des camps d'internement.
• {b}La rupture.{/b} Le coût des camps et de vieilles rancunes divisèrent l'Alliance. {link:gilneas}Gilneas{/link}, {link:stromgarde-keep}Stromgarde{/link} et {link:quel-thalas}Quel'Thalas{/link} la quittèrent. {link:alterac-mountains}Alterac{/link} l'avait déjà trahie au profit de la Horde et avait été déchue de sa couronne.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} La peste et le {link:scourge}Fléau{/link} détruisirent {link:lordaeron}Lordaeron{/link}. {link:jaina-proudmoore}Jaina Proudmoore{/link} mena des survivants vers l'ouest en {link:kalimdor}Kalimdor{/link}, où humains, orcs et elfes de la nuit combattirent côte à côte lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.
• {b}La nouvelle Alliance.{/b} Depuis, {link:stormwind-city}Stormwind{/link} a relevé la bannière que Lordaeron avait laissée tomber. {link:ironforge}Ironforge{/link} se tient à ses côtés, les gnomes de {link:gnomeregan}Gnomeregan{/link} déchue s'abritent parmi les nains, et les elfes de la nuit de {link:darnassus}Darnassus{/link} l'ont rejointe.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[L'Alliance est forte sur le papier et bien mince en vérité. Le roi {link:varian-wrynn}Varian Wrynn{/link} a disparu, et le généralissime {link:bolvar-fordragon}Bolvar Fordragon{/link} gouverne {link:stormwind-city}Stormwind{/link} en tant que régent. Le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} règne sur {link:ironforge}Ironforge{/link}. {link:tyrande-whisperwind}Tyrande Whisperwind{/link} dirige les elfes de la nuit, et {link:jaina-proudmoore}Jaina Proudmoore{/link} tient {link:theramore-isle}Theramore{/link}. Leurs soldats combattent la {link:horde}Horde{/link} en {link:ashenvale}Orneval{/link} et dans les {link:the-barrens}Tarides{/link}, le {link:scourge}Fléau{/link} à {link:lordaeron}Lordaeron{/link} et une dizaine d'ennemis moindres chez eux. On parle souvent de paix avec les orcs, et on s'y fie rarement.]=],
		},
	},
})

Translate("frFR", "horde", {
	title = "Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[La Horde est la ligue des orcs et de leurs alliés : les {link:darkspear-trolls}trolls Darkspear{/link}, les {link:tauren}taurens{/link} et les {link:forsaken}Réprouvés{/link}. Elle naquit sur un autre monde comme un outil des démons. Elle passa en {link:azeroth}Azeroth{/link}, incendia des royaumes et fut brisée. Puis elle renaquit sous un jeune chef de guerre, comme un peuple en quête de liberté. Sa capitale est {link:orgrimmar}Orgrimmar{/link}, dans la terre rouge de {link:durotar}Durotar{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Sur le monde de Draenor, les orcs étaient un peuple fier de clans et de chamans. Le démon {link:kil-jaeden}Kil'jaeden{/link} de la {link:burning-legion}Légion ardente{/link} entreprit d'en faire son arme. Par le chaman {link:ner-zhul}Ner'zhul{/link}, puis par le démoniste {link:gul-dan}Gul'dan{/link}, il leur enseigna la magie gangrenée. Enfin, les chefs de clan burent le sang du démon {link:mannoroth}Mannoroth{/link}, et une soif de sang brûlante les lia à la Légion. Unis en une seule Horde, ils détruisirent les draeneï, et leur monde se flétrit sous leurs pieds.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:first-war}Première Guerre{/link}.{/b} Par la {link:dark-portal}Porte des Ténèbres{/link}, la Horde envahit le royaume d'{link:azeroth}Azeroth{/link} et le détruisit. {link:stormwind-city}Stormwind{/link} tomba, et le roi {link:llane-wrynn}Llane Wrynn{/link} fut tué.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Sous le chef de guerre {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, la Horde marcha vers le nord avec des ogres, des trolls Amani, des gobelins et des dragons rouges asservis. L'{link:alliance}Alliance{/link} la vainquit, et la plupart des orcs survivants furent enfermés dans des camps d'internement.
• {b}La nouvelle Horde.{/b} Dans les camps, les orcs sombrèrent dans une étrange léthargie. Un jeune {link:orcs}orc{/link} élevé en esclave, {link:thrall}Thrall{/link}, se libéra, apprit les anciennes voies des chamans et libéra son peuple. Doomhammer mourut en combattant à ses côtés et lui transmit son marteau et son titre.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} À l'appel du prophète {link:medivh}Medivh{/link}, Thrall mena la Horde en {link:kalimdor}Kalimdor{/link}. Là, il gagna l'amitié des {link:darkspear-trolls}Darkspear{/link} et des taurens de {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. {link:grom-hellscream}Grom Hellscream{/link} tua {link:mannoroth}Mannoroth{/link} et libéra les orcs de sa malédiction du sang. La Horde combattit aux côtés de l'Alliance lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:thrall}Thrall{/link} règne en chef de guerre depuis {link:orgrimmar}Orgrimmar{/link}, nommée en l'honneur de Doomhammer. {link:cairne-bloodhoof}Cairne{/link} dirige les taurens depuis {link:thunder-bluff}Thunder Bluff{/link}, {link:vol-jin}Vol'jin{/link} dirige les {link:darkspear-trolls}Darkspear{/link}, et {link:sylvanas-windrunner}Sylvanas Windrunner{/link} amène les {link:forsaken}Réprouvés{/link} de {link:lordaeron}Lordaeron{/link} aux côtés de la Horde. La paix avec {link:theramore-isle}Theramore{/link} tient, mais de justesse. En {link:ashenvale}Orneval{/link}, des orcs coupent du bois dans les forêts des elfes de la nuit, et le sang coule pour cela. Des fusiliers marins de {link:kul-tiras}Kul Tiras{/link} gardent les côtes, des centaures et des hurans pressent chaque frontière, et le culte démoniaque de la {link:burning-blade}Lame ardente{/link} s'envenime au sein même de {link:durotar}Durotar{/link}.]=],
		},
	},
})

Translate("frFR", "burning-legion", {
	title = "Légion ardente",
	sections = {
		{
			title = "Résumé",
			text = [=[La Légion ardente est une immense armée de démons qui a dévasté d'innombrables mondes. Son maître est {link:sargeras}Sargeras{/link}, un titan déchu qui défendit jadis la création et cherche maintenant à la défaire. Trois fois la Légion a tendu la main vers {link:azeroth}Azeroth{/link}. Trois fois elle a été repoussée, à un prix terrible.]=],
		},
		{
			title = "Origines",
			text = [=[{link:sargeras}Sargeras{/link} fut jadis le plus grand champion des titans, les créateurs des mondes. Au fil d'âges de guerre contre les démons du Néant distordu, il en vint à croire que toute la création était viciée et devait être brûlée. Il se retourna contre les siens et rassembla une armée de démons pour ce faire. Parmi les premiers qu'il corrompit se trouvaient les érédars, dont les chefs {link:kil-jaeden}Kil'jaeden{/link} et {link:archimonde}Archimonde{/link} devinrent ses principaux lieutenants.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La guerre des Anciens.{/b} La {link:queen-azshara}reine Azshara{/link} et ses Bien-nés attirèrent la Légion dans le monde par le {link:well-of-eternity}puits d'Éternité{/link}. Les elfes de la nuit, menés par {link:malfurion-stormrage}Malfurion Stormrage{/link}, ripostèrent lors de la {link:war-of-the-ancients}guerre des Anciens{/link}. La destruction du puits brisa le continent lors de la {link:great-sundering}Fracture{/link} et coupa le chemin aux démons.
• {b}La Horde.{/b} {link:kil-jaeden}Kil'jaeden{/link} corrompit ensuite les orcs de Draenor et en fit une arme. La {link:horde}Horde{/link} qu'il forgea fut lancée contre {link:azeroth}Azeroth{/link} lors de la {link:first-war}Première Guerre{/link} et de la {link:second-war}Deuxième Guerre{/link}.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} La Légion créa le {link:scourge}Fléau{/link} pour préparer le terrain. La peste tua {link:lordaeron}Lordaeron{/link}, et {link:archimonde}Archimonde{/link} lui-même fut invoqué dans le monde à {link:dalaran}Dalaran{/link}. Il marcha sur l'Arbre-Monde, {link:nordrassil}Nordrassil{/link}. Lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, les elfes de la nuit, les humains et les orcs le retinrent assez longtemps pour que les esprits des anciens le détruisent.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:archimonde}Archimonde{/link} est mort, mais la Légion n'a pas quitté {link:azeroth}Azeroth{/link}. Des démons hantent encore les bois corrompus de {link:felwood}Gangrebois{/link}, les ruines d'{link:azshara}Azshara{/link} et les étendues désolées de la {link:desolace}Désolace{/link}. Le culte de la {link:burning-blade}Lame ardente{/link} les sert en secret parmi les orcs. Dans les {link:blasted-lands}Terres foudroyées{/link}, les mages de {link:nethergarde-keep}Rempart-du-Néant{/link} surveillent la {link:dark-portal}Porte des Ténèbres{/link}, guettant le moindre signe de leur retour.]=],
		},
	},
})

Translate("frFR", "scourge", {
	title = "Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Fléau est une armée de morts-vivants, levée par la peste et gouvernée par le roi-liche dans les glaces de Norfendre. Pendant la {link:third-war}Troisième Guerre{/link}, il détruisit le royaume de {link:lordaeron}Lordaeron{/link}, souilla {link:quel-thalas}Quel'Thalas{/link} et rasa {link:dalaran}Dalaran{/link}. Il tient encore une grande partie du nord, et il a toujours faim des vivants.]=],
		},
		{
			title = "Origines",
			text = [=[Après que les orcs l'eurent déçu, {link:kil-jaeden}Kil'jaeden{/link} de la {link:burning-legion}Légion ardente{/link} punit leur ancien chaman {link:ner-zhul}Ner'zhul{/link}. Il arracha le corps de l'{link:orcs}orc{/link} et lia son esprit à une armure scellée dans un bloc de glace. Puis il le jeta en Norfendre et le nomma roi-liche. Sa tâche était de répandre une peste de non-mort à travers les terres humaines et de les préparer pour la Légion. Depuis son Trône de glace, le roi-liche tendit son esprit vers les vivants, et il attira à lui les ambitieux et les désespérés.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La peste.{/b} Le mage {link:kel-thuzad}Kel'Thuzad{/link} entendit l'appel du roi-liche et fonda le {link:cult-of-the-damned}culte des Damnés{/link}. Par le culte, la peste fut répandue dans le grain du nord de {link:lordaeron}Lordaeron{/link}. Ceux qui en mangèrent moururent et se relevèrent en morts-vivants.
• {b}La chute.{/b} Le prince {link:arthas-menethil}Arthas Menethil{/link} traqua la peste jusqu'en Norfendre. Là, il prit la lame runique Deuillegivre et devint le champion du roi-liche. Il revint assassiner son père et livrer Lordaeron aux morts. Il mena ensuite le Fléau à travers {link:quel-thalas}Quel'Thalas{/link}, où il releva Kel'Thuzad en liche, puis jusqu'à {link:dalaran}Dalaran{/link}, où le seigneur démon {link:archimonde}Archimonde{/link} fut invoqué.
• {b}Les chaînes brisées.{/b} Après la chute d'Archimonde au mont Hyjal, l'emprise du roi-liche s'affaiblit. Beaucoup de morts-vivants se libérèrent, et {link:sylvanas-windrunner}Sylvanas Windrunner{/link} les mena sous le nom de {link:forsaken}Réprouvés{/link}. Arthas partit vers le nord au secours du roi-liche.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le Fléau règne toujours sur les {link:eastern-plaguelands}Maleterres{/link}. {link:kel-thuzad}Kel'Thuzad{/link} commande au nom du roi-liche, et ses serviteurs tiennent la cité en ruine de Stratholme, l'école de nécromancie de Scholomance et bien des villes tombées. Des créatures pestiférées rôdent dans les bois, et des abominations gardent les terres mortes. Face à eux se dressent les {link:forsaken}Réprouvés{/link}, la {link:scarlet-crusade}Croisade écarlate{/link} et l'{link:argent-dawn}Aube d'argent{/link}, qui ne s'accordent sur rien d'autre.]=],
		},
	},
})

Translate("frFR", "cult-of-the-damned", {
	title = "Culte des Damnés",
	sections = {
		{
			title = "Résumé",
			text = [=[Le culte des Damnés est le clergé vivant du {link:scourge}Fléau{/link}. Ses membres vénèrent le roi-liche et le servent de leur plein gré, dans l'espoir d'une vie éternelle après la mort. C'est le culte qui porta la peste à {link:lordaeron}Lordaeron{/link}, et ses nécromanciens relèvent encore les morts au nom du roi-liche.]=],
		},
		{
			title = "Origines",
			text = [=[Le culte fut fondé par {link:kel-thuzad}Kel'Thuzad{/link}, un mage du {link:kirin-tor}Kirin Tor{/link} chassé pour son étude interdite de la nécromancie. Il voyagea jusqu'en Norfendre et entendit la voix du roi-liche. Il revint à {link:lordaeron}Lordaeron{/link} en tant que son prophète. Parmi les pauvres et les oubliés du nord, il prêcha une société nouvelle, où tous seraient égaux et où la mort ne serait pas une fin. Des milliers le suivirent, et peu comprirent ce qu'ils avaient rejoint.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La peste.{/b} Le culte répandit une peste de non-mort par les greniers du nord de {link:lordaeron}Lordaeron{/link}. D'{link:ruins-of-andorhal}Andorhal{/link}, du grain souillé partit vers les villages, et les morts commencèrent à se relever.
• {b}La mort et le retour de {link:kel-thuzad}Kel'Thuzad{/link}.{/b} Le prince {link:arthas-menethil}Arthas Menethil{/link} tua Kel'Thuzad à Andorhal. Après qu'Arthas fut passé au service du roi-liche, il porta les restes du nécromancien jusqu'au puits de Soleil de {link:quel-thalas}Quel'Thalas{/link} et le releva en liche.
• {b}Scholomance.{/b} La famille Barov donna au culte son donjon insulaire de {link:caer-darrow}Caer Darrow{/link}. Là, dans la Scholomance, le culte forme de nouveaux nécromanciens.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le culte reste puissant dans les {link:eastern-plaguelands}Maleterres{/link}. Ses acolytes servent dans les ruines de Stratholme et d'{link:ruins-of-andorhal}Andorhal{/link}. Dans la Scholomance, le sombre maître Gandling enseigne la nécromancie à des élèves volontaires. Les agents du culte circulent encore parmi les vivants, en quête de nouvelles recrues et de nouveaux moyens de répandre la peste.]=],
		},
	},
})

Translate("frFR", "scarlet-crusade", {
	title = "Croisade écarlate",
	sections = {
		{
			title = "Résumé",
			text = [=[La Croisade écarlate est un ordre militant de la {link:holy-light}Lumière sacrée{/link}, qui a juré de détruire les morts-vivants de {link:lordaeron}Lordaeron{/link}. Elle naquit du chagrin de la {link:third-war}Troisième Guerre{/link}, et elle est devenue dure et fanatique. La Croisade ne se fie à personne. Elle traque le {link:scourge}Fléau{/link}, mais elle traque aussi les {link:forsaken}Réprouvés{/link}, et elle traite tout étranger comme un porteur possible de la peste.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:fall-of-lordaeron}chute de Lordaeron{/link}, l'ordre de paladins fondé par {link:uther-the-lightbringer}Uther le Porteur de Lumière{/link} était brisé, et beaucoup de ses chevaliers étaient morts. Les survivants se rassemblèrent sous le grand croisé Saidan Dathrohan, un paladin de l'ancien ordre. Ils jurèrent de purifier {link:lordaeron}Lordaeron{/link} de toute trace de la peste, et ils prirent l'écarlate pour couleur. Beaucoup de ceux qui avaient tout perdu face au {link:scourge}Fléau{/link} affluèrent sous leurs bannières.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La croisade.{/b} La Croisade combattit le {link:scourge}Fléau{/link} à travers le nord avec un grand courage et peu de pitié. Elle fortifia le {link:scarlet-monastery}Monastère écarlate{/link} dans les {link:tirisfal-glades}clairières de Tirisfal{/link}, la ville d'{link:hearthglen}Hearthglen{/link} et la cité de {link:tyr-s-hand}Main de Tyr{/link}.
• {b}Les fanatiques.{/b} Avec le temps, la ferveur de la Croisade tourna à la cruauté. Elle commença à purger quiconque elle soupçonnait de porter la peste, et ses inquisiteurs devinrent redoutés parmi les vivants. Certains de ses membres ne purent supporter ce qu'elle était devenue. Ils la quittèrent et fondèrent l'{link:argent-dawn}Aube d'argent{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La Croisade écarlate tient le Monastère à {link:tirisfal-glades}Tirisfal{/link}, où la grande inquisitrice {link:high-inquisitor-whitemane}Whitemane{/link} et le commandant écarlate {link:scarlet-commander-mograine}Mograine{/link} mènent ses chevaliers. Ses forces tiennent aussi {link:hearthglen}Hearthglen{/link} dans les {link:western-plaguelands}Maleterres de l'ouest{/link} et {link:tyr-s-hand}Main de Tyr{/link} dans les {link:eastern-plaguelands}Maleterres de l'est{/link}. Ses patrouilles brûlent les {link:forsaken}Réprouvés{/link} partout où elles les trouvent. Son zèle est réel, et sa force aussi. Sert-elle encore la Lumière ? C'est une question que ses propres membres n'osent plus poser.]=],
		},
	},
})

Translate("frFR", "argent-dawn", {
	title = "Aube d'argent",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Aube d'argent est un ordre qui a juré de défendre {link:azeroth}Azeroth{/link} contre le {link:scourge}Fléau{/link}, la {link:burning-legion}Légion ardente{/link} et toute autre puissance qui voudrait la détruire. Elle se tient à l'écart des rois et des chefs de guerre. Elle accueille quiconque veut combattre les morts-vivants, quelle que soit sa race ou sa bannière, et elle compte ainsi des orcs, des humains, des nains et même des {link:forsaken}Réprouvés{/link} parmi ses amis.]=],
		},
		{
			title = "Origines",
			text = [=[L'Aube naquit de la {link:scarlet-crusade}Croisade écarlate{/link}. Tandis que la Croisade devenait fanatique, certains de ses membres en vinrent à craindre que ses chefs aient perdu leur chemin. Le seigneur {link:lord-maxwell-tyrosus}Maxwell Tyrosus{/link} et d'autres refusèrent de la suivre plus loin. Ils quittèrent la Croisade et fondèrent un nouvel ordre, fidèle aux enseignements de la {link:holy-light}Lumière sacrée{/link} tels qu'ils les comprenaient. Son premier chef fut le seigneur Raymond George.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le combat dans le nord.{/b} Dès ses premiers jours, l'Aube d'argent combattit le {link:scourge}Fléau{/link} à travers les {link:eastern-plaguelands}Maleterres{/link}, souvent avec peu de soldats et encore moins de ravitaillement.
• {b}Un ordre ouvert à tous.{/b} Contrairement à la Croisade, l'Aube ne demande pas qui étaient ses alliés de leur vivant. Elle accepte l'aide de l'{link:alliance}Alliance{/link} comme de la {link:horde}Horde{/link}, et elle juge chacun sur ses seuls actes.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le seigneur {link:lord-maxwell-tyrosus}Maxwell Tyrosus{/link} dirige l'Aube d'argent depuis la {link:light-s-hope-chapel}Chapelle de l'Espoir de Lumière{/link}, dans les {link:eastern-plaguelands}Maleterres de l'est{/link}. Ses camps parsèment les Maleterres, et ses émissaires attendent dans des cités lointaines pour rassembler des alliés. L'Aube récompense ceux qui apportent la preuve des morts qu'ils ont détruits. Ses membres disent que la guerre contre le {link:scourge}Fléau{/link} ne sera gagnée par aucune nation seule.]=],
		},
	},
})

Translate("frFR", "defias-brotherhood", {
	title = "Confrérie défias",
	aliases = { "Défias" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Confrérie défias est une armée de hors-la-loi qui s'est emparée de la {link:westfall}Marche de l'Ouest{/link} et s'attaque aux terres du {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Ses membres portent des bandanas rouges et frappent depuis l'ombre. En son cœur se tiennent les tailleurs de pierre qui rebâtirent {link:stormwind-city}Stormwind{/link} et ne furent jamais payés pour leur travail. Ils entendent prendre ce qui leur est dû, puis prendre la cité elle-même.]=],
		},
		{
			title = "Origines",
			text = [=[Après la {link:second-war}Deuxième Guerre{/link}, la {link:stonemasons-guild}Guilde des tailleurs de pierre{/link} d'{link:edwin-vancleef}Edwin VanCleef{/link} rebâtit {link:stormwind-city}Stormwind{/link} sur ses cendres. Quand leur travail fut achevé, la {link:house-of-nobles}Chambre des nobles{/link} refusa de les payer. Les maçons se soulevèrent, et dans le chaos la reine {link:tiffin-wrynn}Tiffin Wrynn{/link} fut tuée. Les maçons furent chassés de la cité. Menés par VanCleef, ils partirent vers l'ouest, dans les collines et les champs de la {link:westfall}Marche de l'Ouest{/link}, et là ils devinrent la Confrérie défias.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La conquête de la {link:westfall}Marche de l'Ouest{/link}.{/b} Avec l'armée au loin et la couronne silencieuse, la Confrérie prit la Marche de l'Ouest presque sans résistance. Ses membres chassèrent les fermiers de leurs terres et firent du village de {link:moonbrook}Ruisselune{/link} leur place forte.
• {b}L'emprise de la Confrérie.{/b} Des voleurs défias se répandirent en {link:elwynn-forest}Elwynn{/link}, dans les {link:redridge-mountains}Carmines{/link} et dans le {link:duskwood}Bois de la Pénombre{/link}. L'or volé par les kobolds passe à leurs agents, et leurs anneaux portent l'ancienne marque de la guilde des maçons.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La Confrérie gouverne la {link:westfall}Marche de l'Ouest{/link} depuis l'ombre. Sous {link:moonbrook}Ruisselune{/link}, dans les {link:the-deadmines}Mortemines{/link}, les maçons de {link:edwin-vancleef}VanCleef{/link} construisent un grand navire dans un but qu'ils gardent secret. Leurs golems moissonneurs travaillent des champs volés, et leurs bandes tiennent les routes. Seule la Milice populaire de la {link:sentinel-hill}Colline des sentinelles{/link}, menée par {link:gryan-stoutmantle}Gryan Stoutmantle{/link}, leur tient tête. Dans la prison de {link:stormwind-city}Stormwind{/link}, la {link:the-stockade}Prison{/link}, des Défias capturés se sont soulevés et ont pris les cellules pour eux-mêmes.]=],
		},
	},
})

Translate("frFR", "stonemasons-guild", {
	title = "Guilde des tailleurs de pierre",
	sections = {
		{
			title = "Résumé",
			text = [=[La Guilde des tailleurs de pierre était la confrérie de bâtisseurs qui releva {link:stormwind-city}Stormwind{/link} après la {link:second-war}Deuxième Guerre{/link}. Leur talent donna à la cité ses murs blancs et ses grandes tours. La trahison du royaume à leur égard changea ses maîtres maçons en ses ennemis les plus dangereux.]=],
		},
		{
			title = "Origines",
			text = [=[Quand les exilés de {link:stormwind-city}Stormwind{/link} revinrent de {link:lordaeron}Lordaeron{/link}, ils trouvèrent leur capitale en ruine. Le travail de reconstruction échut aux tailleurs de pierre. Leur maître, {link:edwin-vancleef}Edwin VanCleef{/link}, était un artisan aux dons rares, et sous sa conduite la guilde accomplit en quelques années ce qui aurait pu prendre des générations. La cité qui se dresse aujourd'hui est en grande partie leur œuvre.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La trahison.{/b} Quand le travail fut achevé, la {link:house-of-nobles}Chambre des nobles{/link} refusa de payer aux maçons ce qui leur était dû. Les maçons protestèrent, et la protestation devint une émeute. La reine {link:tiffin-wrynn}Tiffin Wrynn{/link} fut tuée dans le chaos.
• {b}L'exil.{/b} Les maçons furent chassés de {link:stormwind-city}Stormwind{/link}. {link:edwin-vancleef}VanCleef{/link} les mena vers l'ouest, où ils devinrent la {link:defias-brotherhood}Confrérie défias{/link}. Les talents qui avaient bâti une cité servirent désormais à élever des forteresses pour des voleurs.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La marque de l'ancienne guilde survit sur les anneaux défias et dans la maçonnerie des {link:the-deadmines}Mortemines{/link}. À travers {link:elwynn-forest}Elwynn{/link} et la {link:westfall}Marche de l'Ouest{/link}, les maçons bâtissent maintenant pour la Confrérie. Les murs de {link:stormwind-city}Stormwind{/link} sont toujours debout, la meilleure preuve de ce dont la guilde était capable.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit ce qu'il advint des maçons qui ne suivirent pas {link:edwin-vancleef}VanCleef{/link} en exil, ni si une guilde de maçons travaille encore aujourd'hui à {link:stormwind-city}Stormwind{/link}.]=],
		},
	},
})

Translate("frFR", "house-of-nobles", {
	title = "Chambre des nobles",
	sections = {
		{
			title = "Résumé",
			text = [=[La Chambre des nobles est l'assemblée des grands seigneurs de {link:stormwind-city}Stormwind{/link}. Ses membres possèdent des terres, des richesses et d'anciens titres, et ils ont depuis longtemps la main sur le trésor et les lois du royaume. C'est leur refus de payer les tailleurs de pierre qui engagea le royaume sur le chemin de ses maux actuels.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quand la Chambre des nobles se réunit pour la première fois. Elle est aussi ancienne que les familles nobles du royaume, et elle a survécu au feu et à l'exil. Quand {link:stormwind-city}Stormwind{/link} fut rebâtie après la {link:second-war}Deuxième Guerre{/link}, la Chambre se tint aux côtés du jeune roi {link:varian-wrynn}Varian Wrynn{/link}, et sa voix pesa lourd dans la nouvelle cour.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les gages des maçons.{/b} La {link:stonemasons-guild}Guilde des tailleurs de pierre{/link} rebâtit la capitale sous la conduite d'{link:edwin-vancleef}Edwin VanCleef{/link}. Quand le travail fut achevé, la Chambre des nobles refusa de payer aux maçons ce qui leur était dû. La protestation des maçons tourna à l'émeute, et la reine {link:tiffin-wrynn}Tiffin Wrynn{/link} mourut dans les violences. Les maçons furent exilés, et ils devinrent la {link:defias-brotherhood}Confrérie défias{/link}.
• {b}La faute.{/b} Beaucoup à {link:stormwind-city}Stormwind{/link} reprochent encore aux nobles la mort de la reine et la naissance des Défias. Les nobles, pour leur part, en rejettent la faute sur les maçons.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Avec le {link:varian-wrynn}roi Varian{/link} disparu, les nobles ont une grande influence sur la régence du généralissime {link:bolvar-fordragon}Bolvar Fordragon{/link}. Dame {link:katrana-prestor}Katrana Prestor{/link} est devenue leur favorite, et ses conseils sont entendus dans chaque débat. Le petit peuple murmure que les seigneurs se disputent sur les impôts pendant que la {link:westfall}Marche de l'Ouest{/link} brûle. Le régent doit garder les nobles satisfaits, et cela ne rend pas sa tâche plus facile.]=],
		},
	},
})

Translate("frFR", "si-7", {
	title = "SI:7",
	sections = {
		{
			title = "Résumé",
			text = [=[Le SI:7 est le service secret du {link:kingdom-of-stormwind}royaume de Stormwind{/link}. Ses agents sont des espions, des éclaireurs et des assassins qui servent la couronne en silence. Ils surveillent les ennemis du royaume, hors de ses murs comme à l'intérieur. Peu de gens à {link:stormwind-city}Stormwind{/link} en savent grand-chose, et c'est ainsi qu'ils le préfèrent.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne dit quand le SI:7 fut fondé ni qui lui donna son nom le premier. Il sert les rois de {link:stormwind-city}Stormwind{/link} depuis avant la {link:third-war}Troisième Guerre{/link}, et ses agents ont toujours travaillé loin de la lumière de la cour.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Dans l'ombre.{/b} Le SI:7 traque les ennemis cachés du royaume depuis de nombreuses années. Il a surveillé les royaumes rivaux, les traîtres de l'intérieur et les cultes dangereux. Ses membres sont surtout tirés des voleurs de {link:stormwind-city}Stormwind{/link}, qui sont formés à son quartier général.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:master-mathias-shaw}Maître Mathias Shaw{/link} dirige le SI:7 depuis son quartier général de la {link:old-town}Vieille ville{/link}, dans la {link:stormwind-city}cité de Stormwind{/link}. Ses agents suivent la {link:defias-brotherhood}Confrérie défias{/link} à travers la {link:westfall}Marche de l'Ouest{/link}, surveillent les alliés de la Confrérie et rendent compte d'étranges agissements chez les {link:forsaken}Réprouvés{/link}. Certains servent à {link:theramore-isle}Theramore{/link} pour protéger le gouvernement de {link:jaina-proudmoore}Jaina Proudmoore{/link}. D'autres ont rejoint les voleurs de {link:ravenholdt-manor}Ravenholdt{/link} dans la guerre contre le {link:syndicate}Syndicat{/link}. Avec le roi disparu et l'armée à l'étranger, le travail discret de Shaw est plus important que jamais.]=],
		},
	},
})

Translate("frFR", "explorers-league", {
	title = "Ligue des explorateurs",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ligue des explorateurs est une société d'érudits et d'aventuriers nains établie à {link:ironforge}Ironforge{/link}. Ses membres fouillent à la recherche de reliques, cartographient des ruines oubliées et étudient les mystères du monde ancien. Par-dessus tout, ils cherchent les véritables origines du {link:dwarves}peuple nain{/link}, et ils croient que la réponse est enfouie dans la pierre.]=],
		},
		{
			title = "Origines",
			text = [=[Les nains ont toujours creusé profond, mais la Ligue a fait de la fouille une science. Depuis la Salle des explorateurs à {link:ironforge}Ironforge{/link}, elle envoie des expéditions à travers le monde et rassemble ce qu'elles trouvent. Ses membres estiment le savoir autant que l'or. Ils sont connus pour leur courage, et tout aussi connus pour leur mépris du danger.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La grande fouille.{/b} La Ligue croit depuis longtemps que les nains furent façonnés dans la pierre par les titans, les créateurs du monde. Ses expéditions ont fouillé des ruines anciennes à travers Khaz Modan et au-delà pour en trouver la preuve.
• {b}Des noms célèbres.{/b} Parmi ses membres se trouve {link:brann-bronzebeard}Brann Bronzebeard{/link}, frère du roi {link:magni-bronzebeard}Magni Bronzebeard{/link}, l'explorateur le plus célèbre de son époque.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le grand explorateur {link:high-explorer-magellas}Magellas{/link} dirige la Ligue depuis la Salle des explorateurs. Ses sites de fouilles sont dispersés à travers le monde : aux {link:ironband-s-excavation-site}Excavations d'Ironband{/link} dans le {link:loch-modan}Loch Modan{/link}, à {link:bael-modan}Bael Modan{/link} dans les {link:the-barrens}Tarides{/link}, et dans les ruines d'{link:uldaman}Uldaman{/link} dans les {link:badlands}Terres ingrates{/link}. Dans les {link:wetlands}Paluns{/link}, les {link:whelgar-s-excavation-site}Excavations de Whelgar{/link} ont mis au jour quelque chose à quoi les fouilleurs n'étaient pas préparés. Les attaques de troggs et les revendications rivales frappent beaucoup de ces sites, mais la Ligue ne renonce pas facilement.]=],
		},
	},
})

Translate("frFR", "cenarion-circle", {
	title = "Cercle cénarien",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cercle cénarien est l'ordre des druides, les gardiens de la nature. Ses membres tirent leur pouvoir de la terre et du {link:emerald-dream}Rêve d'émeraude{/link}, et ils ont juré de protéger le monde vivant. Le Cercle porte le nom du demi-dieu Cénarius. Longtemps ordre des {link:night-elves}elfes de la nuit{/link}, il compte désormais aussi des {link:tauren}taurens{/link} parmi ses membres.]=],
		},
		{
			title = "Origines",
			text = [=[Le premier druide des elfes de la nuit fut {link:malfurion-stormrage}Malfurion Stormrage{/link}, instruit par Cénarius lui-même. Pendant la {link:war-of-the-ancients}guerre des Anciens{/link}, Malfurion et ses disciples employèrent leur art nouveau contre la {link:burning-legion}Légion ardente{/link}. Après la {link:great-sundering}Fracture{/link}, les druides devinrent les gardiens des terres des elfes de la nuit. Pendant des milliers d'années, ils dormirent dans le {link:emerald-dream}Rêve d'émeraude{/link}, ne s'éveillant qu'aux heures de besoin.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Les druides furent réveillés pour affronter la Légion une fois de plus. Ils combattirent lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, où l'Arbre-Monde {link:nordrassil}Nordrassil{/link} fut sacrifié pour détruire {link:archimonde}Archimonde{/link}.
• {b}Un Cercle ouvert.{/b} Depuis, le Cercle a accueilli des druides taurens, le premier d'entre eux étant {link:hamuul-runetotem}Hamuul Runetotem{/link}. Il se tient à l'écart de l'{link:alliance}Alliance{/link} comme de la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le cœur du Cercle est {link:moonglade}Reflet-de-Lune{/link}, un vallon sacré où le gardien {link:keeper-remulos}Remulos{/link}, fils de Cénarius, monte la garde. Ses druides veillent sur les lieux sauvages de {link:kalimdor}Kalimdor{/link} et tentent de guérir la corruption de {link:felwood}Gangrebois{/link}. {link:malfurion-stormrage}Malfurion{/link} s'est retiré dans le {link:emerald-dream}Rêve d'émeraude{/link}. En son absence, l'archidruide {link:fandral-staghelm}Fandral Staghelm{/link} dirige les druides de {link:darnassus}Darnassus{/link}, où l'on a fait croître un nouvel Arbre-Monde, {link:teldrassil}Teldrassil{/link}.]=],
		},
	},
})

Translate("frFR", "earthen-ring", {
	title = "Cercle terrestre",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cercle terrestre est un conseil de chamans voué à l'équilibre des {link:elements}éléments{/link}. Ses membres écoutent les esprits de la terre, du feu, de l'eau et de l'air, et ils s'efforcent de maintenir ces forces en harmonie. Le Cercle se tient au-dessus des querelles des nations. Son regard est tourné vers le monde lui-même.]=],
		},
		{
			title = "Origines",
			text = [=[Le Cercle terrestre fut fondé par les {link:tauren}taurens{/link} il y a longtemps, pour guider leur peuple avec sagesse et maintenir la paix entre les esprits élémentaires. Ses anciens se réunissent en conseil depuis des générations. Les chamans du Cercle ne commandent pas aux éléments. Ils demandent, ils négocient, et ils se souviennent que les esprits ne sont pas des serviteurs.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Les nouveaux chamans.{/b} Quand {link:thrall}Thrall{/link} ramena les orcs aux voies des chamans, les chemins des taurens et des orcs se rejoignirent. Après la {link:third-war}Troisième Guerre{/link}, le Cercle terrestre commença à accueillir des chamans orcs et trolls dans ses cercles.
• {b}Les Réprouvés.{/b} Quand les {link:forsaken}Réprouvés{/link} demandèrent à rejoindre la {link:horde}Horde{/link}, ils affirmèrent chercher un remède à leur non-mort dans les pouvoirs guérisseurs de la terre. Thrall et {link:cairne-bloodhoof}Cairne Bloodhoof{/link} se méfiaient. C'est {link:shadow-council}le Conseil{/link} des anciens du Cercle qui pressa la Horde de les aider.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les chamans du Cercle terrestre veillent sur les éléments de {link:kalimdor}Kalimdor{/link} et au-delà. Ce qu'ils entendent les trouble. Le feu fait rage dans les profondeurs de {link:blackrock-mountain}Blackrock{/link}, et les éléments s'agitent en bien des terres. {link:muln-earthfury}Muln Earthfury{/link}, un {link:tauren}tauren{/link} d'une grande sagesse, dirige le Cercle, bien qu'il se montre rarement.]=],
		},
	},
})

Translate("frFR", "twilight-s-hammer", {
	title = "Marteau du crépuscule",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Marteau du crépuscule est un culte de l'apocalypse. Ce fut autrefois un clan {link:orcs}orc{/link} de la {link:horde}Horde{/link}. C'est aujourd'hui une confrérie de fous de toutes races, qui vénèrent d'anciennes puissances enfouies sous le monde et aspirent à la fin de toutes choses. Là où le culte se rassemble, d'étranges rites se tiennent dans le noir.]=],
		},
		{
			title = "Origines",
			text = [=[Le Marteau du crépuscule était un clan de la {link:horde}Horde{/link} mené par Cho'gall, un {link:ogres}ogre{/link}-mage à deux têtes qui comptait parmi les plus proches serviteurs de {link:gul-dan}Gul'dan{/link}. Même parmi les orcs, ses membres étaient redoutés comme des fanatiques. Ils croyaient que le monde était condamné, et que leur tâche était de hâter sa fin.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La Deuxième Guerre.{/b} Au milieu de la {link:second-war}Deuxième Guerre{/link}, {link:gul-dan}Gul'dan{/link} trahit la {link:horde}Horde{/link} pour chercher la Tombe de {link:sargeras}Sargeras{/link}. Cho'gall et son clan le suivirent. Le chef de guerre {link:orgrim-doomhammer}Orgrim Doomhammer{/link} retourna ses armées contre les traîtres et brisa le clan, et l'{link:alliance}Alliance{/link} profita du chaos. Aucune chronique de cette époque ne rapporte le sort de Cho'gall.
• {b}Le culte renaissant.{/b} Le clan ne mourut pas. Il devint un culte voué aux Dieux très anciens, les sombres puissances emprisonnées au plus profond d'{link:azeroth}Azeroth{/link}. Il commença à attirer des membres de nombreuses races qui partageaient sa soif de ruine.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Le culte œuvre dans des lieux cachés. Ses membres ont été trouvés dans les ruines inondées des {link:blackfathom-deeps}Profondeurs de Brassenoire{/link} en {link:ashenvale}Orneval{/link}, où ils accomplissent de sombres rites parmi les {link:naga}nagas{/link}. On dit que ses camps se trouvent dans le désert de {link:silithus}Silithus{/link}, loin au sud. Nul ne sait combien servent le Marteau, ni à quel point ses membres se tiennent près des trônes du monde.]=],
		},
	},
})

Translate("frFR", "burning-blade", {
	title = "Lame ardente",
	sections = {
		{
			title = "Résumé",
			text = [=[La Lame ardente fut autrefois un clan {link:orcs}orc{/link} de redoutables bretteurs. C'est aujourd'hui surtout un culte d'adorateurs de démons qui se cache parmi les orcs de la nouvelle {link:horde}Horde{/link}. Ses membres servent la {link:burning-legion}Légion ardente{/link} et s'efforcent de replonger leur peuple dans la corruption dont {link:thrall}Thrall{/link} l'a libéré.]=],
		},
		{
			title = "Origines",
			text = [=[Sur Draenor, la Lame ardente était un clan {link:orcs}orc{/link}, célèbre pour ses maîtres-lames. Quand les orcs tombèrent sous le pouvoir des démons, la Lame ardente tomba plus bas que la plupart. Pendant la {link:first-war}Première Guerre{/link} et la {link:second-war}Deuxième Guerre{/link}, ses guerriers formaient une confrérie chaotique, folle de combat et loyale envers personne. On ne les lâchait sur l'ennemi qu'aux heures de grand besoin.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Deux voies.{/b} Après la {link:second-war}Deuxième Guerre{/link}, certains maîtres-lames du clan rejoignirent la nouvelle {link:horde}Horde{/link} de {link:thrall}Thrall{/link} et jurèrent de se libérer de l'emprise démoniaque. D'autres restèrent fidèles aux démons. Sous {link:shadow-council}le Conseil{/link} des ombres, les derniers des démonistes orcs, ceux-là devinrent un culte secret.
• {b}Le culte se répand.{/b} Le culte a accueilli des membres d'autres races, même des humains et des {link:forsaken}Réprouvés{/link}, qui partagent sa dévotion à la Légion.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La Lame ardente s'envenime en {link:durotar}Durotar{/link} et dans les {link:the-barrens}Tarides{/link}. Ses cultistes se cachent dans les cavernes de Durotar, au {link:skull-rock}Rocher du crâne{/link} et à la Caverne des Terrevent, et ils complotent sous {link:orgrimmar}Orgrimmar{/link} même. En {link:desolace}Désolace{/link}, ils tiennent la {link:thunder-axe-fortress}Forteresse de Hache-Tonnerre{/link}, où leurs maîtres démons marchent librement. Les guerriers de la {link:horde}Horde{/link} les traquent sans relâche, mais le culte semble toujours trouver de nouvelles recrues.]=],
		},
	},
})

Translate("frFR", "dark-iron-dwarves", {
	title = "Nains Sombrefer",
	aliases = { "clan Sombrefer", "Sombrefer" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les nains Sombrefer sont les plus redoutés des trois clans nains. Ils sont maîtres du feu et de la magie noire. Il y a deux siècles, ils firent la guerre à leurs frères, et dans leur défaite ils libérèrent un seigneur des flammes qui les asservit. Ils vivent désormais dans les profondeurs du mont {link:blackrock-mountain}Blackrock{/link}, liés au service du Seigneur du feu Ragnaros.]=],
		},
		{
			title = "Origines",
			text = [=[Il y a longtemps, les {link:dwarves}nains{/link} de Khaz Modan ne formaient qu'un seul peuple, gouverné depuis {link:ironforge}Ironforge{/link} par le haut roi Modimus Anvilmar. À la mort de Modimus, trois clans se disputèrent le trône : les Bronzebeard, les Wildhammer et les Sombrefer du thane-sorcier {link:ruins-of-thaurissan}Thaurissan{/link}. Les Bronzebeard l'emportèrent et chassèrent les autres. Les Sombrefer partirent vers le sud et bâtirent la cité de Thaurissan parmi les montagnes.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La guerre des Trois Marteaux.{/b} Quelque deux cent trente ans avant la {link:dark-portal}Porte des Ténèbres{/link}, les Sombrefer attaquèrent à la fois {link:ironforge}Ironforge{/link} et {link:grim-batol}Grim Batol{/link}, le siège des Wildhammer. Ils furent vaincus aux portes d'Ironforge.
• {b}La venue de Ragnaros.{/b} En désespoir de cause, {link:ruins-of-thaurissan}Thaurissan{/link} chercha une grande puissance pour l'aider. Il invoqua Ragnaros, seigneur des élémentaires de feu. La venue du Seigneur du feu déchira la terre et créa la {link:searing-gorge}Gorge des Vents brûlants{/link} et les {link:burning-steppes}Steppes ardentes{/link}. Le mont {link:blackrock-mountain}Blackrock{/link} s'éleva là où s'était dressée la cité, et les Sombrefer devinrent les esclaves de Ragnaros.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[L'empereur Dagran {link:ruins-of-thaurissan}Thaurissan{/link} règne sur les Sombrefer depuis la cité d'Ombreforge, au cœur du mont {link:blackrock-mountain}Blackrock{/link}. Ragnaros les gouverne tous depuis le Cœur du Magma, en contrebas. Les forces Sombrefer razzient la {link:searing-gorge}Gorge des Vents brûlants{/link}, creusent dans les {link:badlands}Terres ingrates{/link} et menacent les {link:wetlands}Paluns{/link}. Le roi {link:magni-bronzebeard}Magni Bronzebeard{/link} soutient que sa fille Moira fut enlevée par l'empereur, et il veut la reprendre.]=],
		},
	},
})

Translate("frFR", "steamwheedle-cartel", {
	title = "Cartel Gentepression",
	aliases = { "Gentepression" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cartel Gentepression est la plus grande des compagnies de commerce gobelines. Il possède des ports et des villes des deux côtés de la mer, et il les garde ouverts à tout client qui a de l'or. Le Cartel n'a qu'une loyauté : le profit. Sa neutralité l'a enrichi, et il la protège avec des gros bras à gages.]=],
		},
		{
			title = "Origines",
			text = [=[Les gobelins servirent l'ancienne {link:horde}Horde{/link} pendant la {link:second-war}Deuxième Guerre{/link}. Le prince marchand du cartel vendit aux orcs des machines, des cartes, de l'alchimie et des zeppelins, et il construisit des navires pour la flotte de Doomhammer. Quand la Horde fut vaincue, les gobelins en tirèrent une leçon. Il était plus rentable de vendre aux deux camps que de prendre parti pour l'un d'eux.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}{link:booty-bay}Baie-du-Butin{/link}.{/b} Avant la {link:first-war}Première Guerre{/link}, les gobelins du Cartel chassèrent les trolls d'un petit port à la pointe sud de {link:stranglethorn-vale}Strangleronce{/link}. Ils en firent leur port de Baie-du-Butin.
• {b}Par-delà la mer.{/b} Dans les années qui suivirent, le Cartel bâtit ou revendiqua des villes à travers {link:kalimdor}Kalimdor{/link} : {link:ratchet}Ratchet{/link} sur la côte des {link:the-barrens}Tarides{/link}, {link:gadgetzan}Gadgetzan{/link} dans le désert de {link:tanaris}Tanaris{/link}, et {link:everlook}Long-guet{/link} dans le nord glacé du {link:winterspring}Berceau-de-l'Hiver{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les villes du Cartel sont des havres où orcs et humains peuvent commercer sans tirer l'épée. Leurs cogneurs maintiennent la paix d'une main lourde. Le baron {link:baron-revilgaz}Revilgaz{/link} gouverne {link:booty-bay}Baie-du-Butin{/link}, {link:gazlowe}Gazlowe{/link} veille sur {link:ratchet}Ratchet{/link}, et le maire {link:marin-noggenfogger}Noggenfogger{/link} administre {link:gadgetzan}Gadgetzan{/link}. Chaque ville lutte contre les pirates, les compagnies rivales et les terres sauvages qui l'entourent. Beaucoup de ses ennuis viennent de la {link:venture-company}KapitalRisk{/link}, un cartel gobelin qui n'a aucune de ses manières.]=],
		},
	},
})

Translate("frFR", "venture-company", {
	title = "La KapitalRisk",
	aliases = { "KapitalRisk" },
	sections = {
		{
			title = "Résumé",
			text = [=[La KapitalRisk est un cartel gobelin qui dépouille le monde de ses richesses. Si une chose peut être extraite, abattue ou pompée du sol, la KapitalRisk la prendra, et elle se moque bien de qui vivait là avant. Ses déchiqueteuses et ses foreuses laissent derrière elles des lacs empoisonnés et des collines nues.]=],
		},
		{
			title = "Origines",
			text = [=[Aucune chronique ne rapporte la fondation de la KapitalRisk. C'est l'un des cartels gobelins d'Undermine, et depuis de nombreuses années elle est dirigée par son président, le magnat Razdunk. Contrairement au {link:steamwheedle-cartel}Cartel Gentepression{/link}, elle n'entretient aucune ville neutre et ne prétend à aucun honneur.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}En Kalimdor.{/b} La compagnie vint en {link:kalimdor}Kalimdor{/link} après la {link:third-war}Troisième Guerre{/link} et commença à le piller. Elle pompa du pétrole dans la {link:the-sludge-fen}Videfange{/link} des {link:the-barrens}Tarides{/link}. Elle coupa les forêts des {link:stonetalon-mountains}Serres-Rocheuses{/link}, et elle creusa les falaises de {link:mulgore}Mulgore{/link} après que les {link:tauren}taurens{/link} lui en eurent refusé le droit.
• {b}Dans les {link:eastern-kingdoms}Royaumes de l'est{/link}.{/b} À {link:stranglethorn-vale}Strangleronce{/link}, la compagnie défricha la jungle pour son bois et creusa pour trouver des cristaux rares. Elle a aussi vendu de sombres secrets à la {link:defias-brotherhood}Confrérie défias{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[La KapitalRisk est à l'œuvre à travers le monde. Elle souille les {link:water-wells-of-mulgore}puits de Mulgore{/link} et déchire les forêts des {link:stonetalon-mountains}Serres-Rocheuses{/link} avec de grandes machines. Les taurens, les elfes de la nuit et les gobelins de {link:steamwheedle-cartel}Gentepression{/link} la comptent tous parmi leurs ennemis. Ses contremaîtres s'en moquent, tant que le minerai continue d'arriver.]=],
		},
	},
})

Translate("frFR", "syndicate", {
	title = "Syndicat",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Syndicat est une ligue criminelle des nobles déchus d'{link:alterac-mountains}Alterac{/link}. Il est fait de voleurs, d'assassins et de brigands qui servent des seigneurs sans royaume. Ses membres s'en prennent aux montagnes d'Alterac, aux {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link} et aux {link:arathi-highlands}Hautes-terres d'Arathi{/link}, et ils rêvent d'une couronne qui leur fut prise.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant la {link:second-war}Deuxième Guerre{/link}, le seigneur {link:aiden-perenolde}Aiden Perenolde{/link}, roi d'{link:alterac-mountains}Alterac{/link}, trahit l'{link:alliance}Alliance de Lordaeron{/link} au profit de la {link:horde}Horde{/link}. Quand la guerre fut finie, Alterac fut dépouillé de sa couronne et de ses terres. Les nobles d'Alterac ne pardonnèrent jamais aux autres royaumes. Menés par l'héritier de Perenolde, le seigneur {link:lord-aliden-perenolde}Aliden Perenolde{/link}, ils rassemblèrent voleurs et mercenaires et en firent le Syndicat.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Avant la {link:third-war}Troisième Guerre{/link}.{/b} Des bandits du Syndicat sévissaient déjà dans les bois d'{link:alterac-mountains}Alterac{/link} avant que la peste ne frappe {link:lordaeron}Lordaeron{/link}.
• {b}Après la chute.{/b} Quand Lordaeron tomba, le Syndicat se répandit dans les ruines qu'il laissa derrière lui. Il s'empara du {link:durnholde-keep}Donjon de Durnholde{/link} dans les {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link} et d'une grande partie de {link:stromgarde-keep}Stromgarde{/link} dans les {link:arathi-highlands}Hautes-terres d'Arathi{/link}.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:lord-aliden-perenolde}Aliden Perenolde{/link} dirige le Syndicat depuis le {link:dandred-s-fold}Clos de Dandred{/link} dans les {link:alterac-mountains}montagnes d'Alterac{/link}, et le Syndicat tient la ville de {link:strahnbrad}Strahnbrad{/link} comme une forteresse. Le seigneur {link:lord-falconcrest}Falconcrest{/link} commande ses forces dans les ruines de {link:stromgarde-keep}Stromgarde{/link}. Il vole des chevaux et des cargaisons à {link:southshore}Southshore{/link} et tend des embuscades aux soldats de Stromgarde. Les voleurs de {link:ravenholdt-manor}Ravenholdt{/link} lui mènent une longue guerre, et les {link:forsaken}Réprouvés{/link} ont mis à prix la tête de chacun de ses membres.]=],
		},
	},
})

Translate("frFR", "royal-apothecary-society", {
	title = "Société royale des apothicaires",
	sections = {
		{
			title = "Résumé",
			text = [=[La Société royale des apothicaires est l'ordre d'alchimistes qui sert {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, la reine banshee des {link:forsaken}Réprouvés{/link}. Dans les caveaux sous {link:undercity}Undercity{/link}, ses apothicaires préparent des poisons et des pestes. Leur but affiché est un remède à la non-mort. Leur but véritable est plus sombre.]=],
		},
		{
			title = "Origines",
			text = [=[La Société fut fondée par {link:sylvanas-windrunner}Sylvanas{/link} après que les {link:forsaken}Réprouvés{/link} eurent conquis leur liberté face au {link:scourge}Fléau{/link}. Ses apothicaires entreprirent ce qu'aucun alchimiste vivant n'osait : prendre la peste qui avait fait les Réprouvés et en faire une arme à eux. Les apothicaires installèrent leurs laboratoires dans l'{link:the-apothecarium}Apothicarium{/link}, sous le {link:royal-quarter}Quartier royal{/link} d'{link:undercity}Undercity{/link}.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le remède et la peste.{/b} Quand les {link:forsaken}Réprouvés{/link} rejoignirent la {link:horde}Horde{/link}, ses autres peuples crurent que les apothicaires cherchaient un remède à leur condition. En vérité, la première œuvre de la Société fut une nouvelle peste, destinée à détruire le {link:scourge}Fléau{/link}.
• {b}D'autres arts.{/b} La Société a aussi relevé des chevaux morts pour servir de montures aux Réprouvés, et elle envoie ses membres au loin pour rassembler de nouveaux ingrédients.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Dans l'{link:the-apothecarium}Apothicarium{/link}, le maître apothicaire {link:master-apothecary-faranell}Faranell{/link} supervise le travail sur la nouvelle peste, et les agents de la Société l'essaient dans les champs d'{link:hillsbrad-foothills}Hillsbrad{/link} et ailleurs. Ses apothicaires servent dans chaque avant-poste réprouvé. Leurs alliés de la {link:horde}Horde{/link} les observent avec un malaise croissant.]=],
		},
	},
})

Translate("frFR", "darkspear-trolls", {
	title = "Trolls Darkspear",
	aliases = { "tribu Darkspear", "Darkspear" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Darkspear sont une tribu de {link:trolls}trolls{/link} de la jungle qui se tient aux côtés de la {link:horde}Horde{/link}. Ils étaient des parias et des errants jusqu'à ce que {link:thrall}Thrall{/link} les sauve de la destruction. Ils sont désormais les alliés les plus loyaux des orcs. Ce sont des chasseurs, des sorciers-docteurs et de farouches guerriers, et ils doivent leur survie au chef de guerre.]=],
		},
		{
			title = "Origines",
			text = [=[Les Darkspear étaient autrefois une tribu des Gurubashi, les trolls de la jungle de {link:stranglethorn-vale}Strangleronce{/link}. Quand l'empire Gurubashi s'effondra, ses tribus se retournèrent les unes contre les autres, et les Darkspear furent chassés. Ils se firent un nouveau foyer sur des îles des mers du sud.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le sauvetage.{/b} Quand la flotte de {link:thrall}Thrall{/link} fut jetée sur leur île par une tempête, les Darkspear étaient en grand danger. Des humains de {link:kul-tiras}Kul Tiras{/link} et des murlocs de la mer les attaquaient. Thrall combattit à leurs côtés, et leur chef, Sen'jin, fut capturé. Sen'jin mourut captif des murlocs, mais il avait prévu que Thrall mènerait son peuple vers un nouveau foyer.
• {b}Kalimdor.{/b} Les Darkspear firent voile avec la {link:horde}Horde{/link} vers {link:kalimdor}Kalimdor{/link} et s'installèrent sur les {link:echo-isles}Îles de l'Écho{/link}, au large de la côte de {link:durotar}Durotar{/link}.
• {b}{link:zalazane}Zalazane{/link}.{/b} Un sorcier-docteur nommé Zalazane se retourna contre sa tribu. Par un vaudou noir, il asservit beaucoup de trolls des Îles de l'Écho et chassa les autres de leurs foyers.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les Darkspear libres se sont installés sur la côte de {link:durotar}Durotar{/link}, dans le village qu'ils nommèrent d'après Sen'jin. Le fils de Sen'jin, {link:vol-jin}Vol'jin{/link}, les dirige et se tient aux côtés de {link:thrall}Thrall{/link} à {link:orgrimmar}Orgrimmar{/link}. {link:zalazane}Zalazane{/link} règne toujours sur les {link:echo-isles}Îles de l'Écho{/link}, et les Darkspear entendent les reprendre.]=],
		},
	},
})

Translate("frFR", "kingdom-of-ironforge", {
	title = "Royaume d'Ironforge",
	sections = {
		{
			title = "Résumé",
			text = [=[Le royaume d'{link:ironforge}Ironforge{/link} est le royaume des {link:dwarves}nains{/link} Bronzebeard. Sa capitale est taillée au cœur d'une montagne de {link:dun-morogh}Dun Morogh{/link}, et ses forges brûlent depuis des milliers d'années. C'est un royaume de mineurs, de forgerons, d'ingénieurs et d'érudits. C'est aussi l'un des deux piliers de l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Origines",
			text = [=[Les nains disent qu'ils furent façonnés dans la pierre aux âges passés. Leur plus vieille cité est {link:ironforge}Ironforge{/link}, et longtemps tous les nains furent gouvernés depuis elle. Quand le haut roi Modimus Anvilmar mourut, les clans Bronzebeard, Wildhammer et Sombrefer se disputèrent le trône. Les Bronzebeard tinrent Ironforge et chassèrent les deux autres clans. Lors de la guerre des Trois Marteaux, ils vainquirent les {link:dark-iron-dwarves}Sombrefer{/link} aux portes de la cité.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Amis des hommes.{/b} Des explorateurs d'{link:arathor}Arathor{/link} atteignirent Khaz Modan il y a longtemps. Les nains et les humains devinrent amis et échangèrent leurs savoirs de la forge, de l'ingénierie et de la magie.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Quand la {link:horde}Horde{/link} envahit Khaz Modan, {link:ironforge}Ironforge{/link} elle-même tint bon. Les nains rejoignirent l'{link:alliance}Alliance de Lordaeron{/link}, et ils n'oublièrent pas qui s'était tenu à leurs côtés.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Le frère du roi {link:magni-bronzebeard}Magni Bronzebeard{/link}, {link:muradin-bronzebeard}Muradin Bronzebeard{/link}, partit en Norfendre avec le prince {link:arthas-menethil}Arthas Menethil{/link} et ne revint jamais. Les nains le pleurent comme perdu.
• {b}La chute de Gnomeregan.{/b} Quand {link:gnomeregan}Gnomeregan{/link} fut perdue, Magni donna un foyer dans sa cité aux {link:gnomes}gnomes{/link} survivants.]=],
